package com.jamshed.hrms.controller;
import com.jamshed.hrms.dto.EmployeeRequest; import com.jamshed.hrms.entity.Employee; import com.jamshed.hrms.service.EmployeeService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/employees") public class EmployeeController { private final EmployeeService s; public EmployeeController(EmployeeService s){this.s=s;}
 @GetMapping public List<Employee> all(){return s.all();} @GetMapping("/{id}") public Employee one(@PathVariable Long id){return s.one(id);} @PostMapping public Employee create(@Valid @RequestBody EmployeeRequest r){return s.create(r);} @PutMapping("/{id}") public Employee update(@PathVariable Long id,@Valid @RequestBody EmployeeRequest r){return s.update(id,r);} @PatchMapping("/{id}/status") public Employee status(@PathVariable Long id,@RequestParam String value){return s.status(id,value);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);} }
